import { getCompareGoodsList, getCompareDetail } from '@utils/fetch.js';
import { createApp } from 'vue/dist/vue.esm-bundler'
import { gaPushDataLayer, calcTop } from '@utils/index'

// 下拉
$(document).ready(function() {
    const vm = createApp({
        delimiters: ['${', '}'],
        data() {

            return {
                isMobile: document.body.clientWidth < 1024,
                productTypes: [],
                selectProductTypeId: '',
                selectProductList: [],
                productList: [],
                skuIdList: [],
                showDiff: false,
                openDropdown: null,
                selectIndex: null,
                detailList: [], // 详情
                ids: '',
                pageLoading: false,
                productLoading: false,
                detailLoading: false,
                money_format: window.pageInfo.currency.money_format,
                formatMoney: window.formatMoney,
                top: calcTop()
            }
        },

        async created() {
            this.productTypes = JSON.parse(document.querySelector("#compare-detail-type")?.innerText || "[]")
            if (this.productTypes.length > 0 ) {
                this.selectProductTypeId = this.productTypes[0].id
                // 获取
                this.pageLoading = true
                await this.getGoodsList()
                this.getDetail()
                this.pageLoading = false
            }
        },
        mounted() {
            this.onEvent()
        },
        methods: {
            onEvent() {
                const that = this
                // 监听
                const el = document.querySelector('.header-after-sales')
                const targetClass = "show";
                if (!el) return
                let observer = new MutationObserver(mutations => {
                    mutations.forEach(function(mutation) {
                        if ( mutation.type === "attributes" && mutation.attributeName === 'class') {
                            const hasClass = el.classList.contains(targetClass);
                            if (hasClass) {
                                that.top = calcTop() + $('.header-after-sales').outerHeight() - 1 || 0
                            } else {
                                that.top = calcTop() - 1 || 0
                            }
                        }
                    });
                })
                observer.observe(el, { attributes: true, attributeFilter: ["class"] })
            },
            // 类型点击
            async handleTypeItemClick(item) {
                this.pageLoading = true
                const { id, title } = item
                this.selectProductTypeId = id
                await this.getGoodsList()
                this.getDetail()
                gaPushDataLayer('products_compare_4.0_user_clicks', {
                    module: "Products Type",
                    position: title
                })
                this.pageLoading = false
            },
            // 获取产品列表
            async getGoodsList() {
                this.productLoading = true
                try {
                    const params = {
                        pageNum: this.selectProductTypeId,
                    }
                    const { data: { classifyGoodsResps = [], skuIdList = [] } } = await getCompareGoodsList(params)
                    this.productList = classifyGoodsResps || []
                    this.skuIdList = this.isMobile ? skuIdList.slice(0, 2) : skuIdList
                } catch (error) {
                } finally {
                    this.productLoading = false
                }
            },
            async getDetail() {
                if (this.skuIdList.length === 0 ) {
                    this.selectProductList = []
                    this.detailList = []
                    return false
                }
                this.detailLoading = true
                try {
                    const params = {
                        skuIdList: this.skuIdList,
                        showDiff: this.showDiff,
                        pageType: 3
                    }
                    const { data } = await getCompareDetail(params)
                    this.selectProductList = this.isMobile ? data.fourProductResps.slice(0, 2) : data.fourProductResps
                    // 处理返回数据
                    this.handleProcessData(data.dictInfoResps)
                } catch (error) {
                } finally {
                    this.detailLoading = false
                }
            },
            // 产品输入框点击
            handleOpen(index) {
                this.openDropdown = index == this.openDropdown ? null : index
            },
            // 产品选择
            handleProductSelect(item, classifyTitle, index) {
                const {skuId, title } = item
                this.openDropdown = null
                if (skuId === this.skuIdList[index]) return
                // 判断数据是否存在值
                if (this.skuIdList.includes(skuId)) {
                    const j = this.skuIdList.findIndex(item => item === skuId)
                    const id = this.skuIdList[j]
                    this.skuIdList[j] = this.skuIdList[index]
                    this.skuIdList[index] = id
                } else {
                    this.skuIdList[index] = skuId
                }
                gaPushDataLayer('products_compare_4.0_user_clicks', {
                    module: "Products Choose",
                    position: classifyTitle,
                    title
                })
                this.getDetail()
            },
            // 加购
            handleAddToCart(item, index, button_name) {
                const that = this
                that.selectIndex = index
                const cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
                const fetchJSON = (url, config) => {
                    return fetch(url, config).then(function(response) {
                        if (!response.ok) {
                        throw response;
                        }
                        return response.json();
                    });
                }
                const config = {
                    credentials: 'same-origin',
                    headers: {
                        'X-Requested-With': 'XMLHttpRequest',
                        'Content-Type': 'application/json;'
                    },
                    method: 'POST',
                    body: JSON.stringify({
                        items: [
                            {
                                id: item.skuId,
                                quantity: 1
                            }
                        ]
                    })
                }
                fetchJSON('/cart/add.js', config).then(response => {
                    if(cart && cart.renderContents) {
                        cart.renderContents(response);
                    } else {
                        window.location.href = '/cart';
                    }
                    gaPushDataLayer('products_compare_4.0_user_clicks', {
                        module: "Buy Now",
                        position: this.selectProductList.map(item => item.title).join(','),
                        button_name
                    })
                }).catch((e) => {
                    e.json().then(errorData => {
                        const message = errorData.message
                        message && pushErrorMessage(message)
                    })
                }).finally(() => {
                    setTimeout(() => that.selectIndex = null, 1000)
                    if (cart && cart.classList.contains('is-empty')) {
                        cart.classList.remove('is-empty');
                    }
                })
            },
            // 级别点击
            handleLevelClick(item) {
                item.show = !item.show
            },
            // Show Diff
            handleDiffChange(button_name) {
                this.getDetail()
                gaPushDataLayer('products_compare_4.0_user_clicks', {
                    module: "Differences",
                    position: this.selectProductList.map(item => item.title).join(','),
                    button_name
                })
            },
            handleGaImage(item) {
                const { title, goodUrl, skuId } = item
                gaPushDataLayer('products_compare_4.0_user_clicks', {
                    module: "Buy Now",
                    position: title,
                    button_name: 'picture',
                    link: `${goodUrl}?variant=${skuId}`
                })
            },
            // 处理数据
            handleProcessData(data = []) {
                // 递归处理数据,添加show属性
                const processTreeData = (items) => {
                    return items.map(item => {
                        const newItem = { ...item, show: true }
                        if (newItem.childInfos && newItem.childInfos.length > 0) {
                            newItem.childInfos = newItem.childInfos.map(child => ({
                                ...child,
                                show: true,
                                childInfos: child.childInfos ? processTreeData(child.childInfos) : []
                            }))
                        }
                        return newItem
                    })
                }
                this.detailList = processTreeData(data)
            }
        },
    }).mount('#compare-detail')
})
